# Fill tags: use explicit ones where given, else derive from title + category,
# and always include the category's broad tag(s).
for _e in ENTRIES:
    _base = _CATEGORY_TAGS.get(_e["cat"], [])
    if _e.get("tags"):
        _e["tags"] = sorted(set([t.lower() for t in _e["tags"]] + _base))
    else:
        _e["tags"] = sorted(set(_title_tags(_e["title"]) + _base))
